const TMDB_IMG="https://image.tmdb.org/t/p/w300";async function fetchShows(e){const t=document.querySelector(`[data-tab-id="${e}"]`);if(t){renderSkeletons(t);try{const o=await fetch(`/api/tmdb?tab=${encodeURIComponent(e)}`);if(!o.ok)throw new Error(`API ${o.status}`);renderPosters(t,(await o.json()).results.slice(0,6))}catch(e){renderError(t,"Não foi possível carregar os títulos. Tente novamente mais tarde."),console.warn("[TMDB]",e.message)}}}function renderSkeletons(e){e.innerHTML=Array.from({length:6}).map(()=>'<li class="shows__list__item shows__list__item--skeleton" aria-hidden="true"></li>').join("")}function renderPosters(e,t){const o=t.filter(e=>e.poster_path).map(e=>{const t=e.title||e.name||"Título desconhecido";return`<li class="shows__list__item">\n        <img src="${`${TMDB_IMG}${e.poster_path}`}" alt="${t}" loading="lazy" />\n      </li>`});e.innerHTML=o.length?o.join(""):'<li class="shows__list__item--error">Sem resultados disponíveis.</li>'}function renderError(e,t){e.innerHTML=`<li class="shows__list__item--error">${t}</li>`}function ocultaElementosDoHeader(){document.querySelector("header").classList.add("header--is-hidden")}function exibeElementosDoHeader(){document.querySelector("header").classList.remove("header--is-hidden")}function abreOuFechaResposta(e){const t=e.target.parentNode.classList.toggle("faq__questions__item--is-open");e.target.setAttribute("aria-expanded",t?"true":"false")}function removeBotaoAtivo(){const e=document.querySelectorAll("[data-tab-button]");for(let t=0;t<e.length;t++)e[t].classList.remove("shows__tabs__button--is-active")}function escondeTodasAbas(){const e=document.querySelectorAll("[data-tab-id]");for(let t=0;t<e.length;t++)e[t].classList.remove("shows__list--is-active")}document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll("[data-tab-button]"),t=document.querySelectorAll("[data-faq-question]"),o=document.querySelector(".hero").clientHeight;fetchShows("em_breve"),fetchShows("populares"),fetchShows("star_plus"),window.addEventListener("scroll",function(){window.scrollY<o?ocultaElementosDoHeader():exibeElementosDoHeader()});for(let t=0;t<e.length;t++)e[t].addEventListener("click",function(e){const t=e.target.dataset.tabButton,o=document.querySelector(`[data-tab-id=${t}]`);escondeTodasAbas(),o.classList.add("shows__list--is-active"),removeBotaoAtivo(),e.target.classList.add("shows__tabs__button--is-active")}),e[t].addEventListener("keydown",function(o){"Enter"!==o.key&&" "!==o.key||(o.preventDefault(),e[t].click())});for(let e=0;e<t.length;e++)t[e].addEventListener("click",abreOuFechaResposta),t[e].addEventListener("keydown",function(o){"Enter"!==o.key&&" "!==o.key||(o.preventDefault(),t[e].click())})});